import { supabase } from "./supabase.js";
export async function showInbox(user) {
  const { data } = await supabase.from("messages").select("id, sender_id, content, created_at").order("created_at", { ascending: false });
  document.getElementById("panel").innerHTML = (data ?? []).map((m) => `<li>${m.content}</li>`).join("");
}
export async function send(user, content) {
  await supabase.from("messages").insert({ sender_id: user.id, content });
}
